// 获取章节题目
function getChapterQuestions(chapterId) {
    return EXAM_QUESTIONS[chapterId] || [];
}

// 获取章节题目统计
function getChapterQuestionStats(chapterId) {
    const questions = getChapterQuestions(chapterId);
    const stats = { total: questions.length, choice_single: 0, choice_multi: 0, true_false: 0, fill_blank: 0, essay: 0, practice: 0, totalScore: 0 };
    questions.forEach(q => { if (stats[q.questionType] !== undefined) stats[q.questionType]++; stats.totalScore += q.score; });
    return stats;
}